  .waitlist-card {
    max-width: 560px; margin: 0 auto;
    background: var(--bg2); border: 1px solid var(--border-strong);
    border-radius: 20px; padding: 48px 40px;
  }
  .waitlist-card h2 { font-size: 2rem; font-weight: 800; color: #fff; margin-bottom: 12px; }
  .waitlist-card p { color: var(--text2); margin-bottom: 32px; font-size: 0.95rem; }
  .waitlist-form { display: flex; gap: 10px; flex-wrap: wrap; }
  .waitlist-form input {
    flex: 1; min-width: 200px; padding: 13px 16px;
    background: rgba(255,255,255,0.05); border: 1px solid var(--border-strong);
    border-radius: 8px; color: var(--text); font-size: 0.9rem; font-family: var(--font);
    outline: none; transition: border-color 0.2s;
  }
  .waitlist-form input:focus { border-color: var(--cyan); }
  .waitlist-form input::placeholder { color: var(--text3); }
