    cursor: pointer; transition: opacity 0.2s; white-space: nowrap;
  }
  .waitlist-submit:hover { opacity: 0.9; }
  .waitlist-note { font-size: 0.78rem; color: var(--text3); margin-top: 14px; }
  .waitlist-success { display: none; text-align: center; padding: 20px; }
  .waitlist-success .checkmark { font-size: 2.5rem; margin-bottom: 12px; }
  .waitlist-success h3 { color: var(--green); font-size: 1.1rem; margin-bottom: 6px; }
  .waitlist-success p { color: var(--text2); font-size: 0.88rem; }

