  .footer-col h4 { font-size: 0.78rem; font-weight: 700; text-transform: uppercase; letter-spacing: 0.12em; color: var(--text3); margin-bottom: 16px; }
  .footer-col a { display: block; font-size: 0.88rem; color: var(--text2); margin-bottom: 10px; transition: color 0.2s; }
  .footer-col a:hover { color: var(--text); text-decoration: none; }
  .footer-bottom { max-width: 1200px; margin: 32px auto 0; padding-top: 24px; border-top: 1px solid var(--border); display: flex; justify-content: space-between; align-items: center; flex-wrap: wrap; gap: 12px; }
  .footer-legal { font-size: 0.78rem; color: var(--text3); }
  .disclaimer {
    background: rgba(245,158,11,0.06); border: 1px solid rgba(245,158,11,0.15);
